"""Persona space, set S3 (em/persona_space/PREREG.md, overnight study): ~1,500 characters generated by gpt-6-luna, 100
per category in 15 categories, as {name, description}, de-duplicated against each other and against the 275 Assistant
Axis roles. Writes em/persona_space/personas_s3.jsonl.
  set -a; source ~/.secrets; set +a
  ~/.venvs/em-judge/bin/python -I em/persona_space/build_personas.py
"""
import asyncio
import csv
import json
import os
import re
from pathlib import Path

from openai import AsyncOpenAI

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "em" / "persona_space" / "personas_s3.jsonl"
MODEL = "gpt-6-luna"
CATEGORIES = [
    "everyday jobs", "skilled trades and crafts", "professions (medicine, law, science, finance)",
    "arts, media and entertainment", "sports, outdoors and adventure", "family and household roles",
    "life stages and life situations", "community, civic and political roles", "historical and period roles",
    "fictional and literary archetypes", "folklore, myth and religion", "internet and subculture identities",
    "animals and creatures", "machines, AIs and science-fiction beings", "personality types (as kinds of people)",
]
PROMPT = """List 100 distinct kinds of character in the category "{cat}".

Cover the category broadly, as it occurs in books, news and everyday conversation, including admirable, ordinary and \
disreputable examples in their natural proportions. Do not organise or select the list by morality. Use generic types, \
not named real people. Each entry: a short name (1-4 words, lowercase) and a one-sentence neutral description of what \
the character is or does.

Return only a JSON array of objects with keys "name" and "description"."""


def norm(s):
    return re.sub(r"[^a-z0-9 ]", "", s.lower().replace("_", " ")).strip()


async def one(client, cat):
    for attempt in range(5):
        try:
            r = await client.chat.completions.create(model=MODEL, messages=[{"role": "user", "content": PROMPT.format(
                cat=cat)}], reasoning_effort="low", max_completion_tokens=12000)
            txt = r.choices[0].message.content
            items = json.loads(txt[txt.index("["):txt.rindex("]") + 1])
            return [dict(name=str(x["name"]).strip(), description=str(x["description"]).strip(), category=cat)
                    for x in items if x.get("name") and x.get("description")]
        except Exception as e:  # noqa: BLE001
            print(f"{cat}: attempt {attempt} failed ({type(e).__name__})", flush=True)
            await asyncio.sleep(2 ** attempt)
    return []


async def main():
    client = AsyncOpenAI(api_key=os.environ["OPENAI_API_KEY"])
    lists = await asyncio.gather(*[one(client, c) for c in CATEGORIES])
    s1 = {norm(r["name"]) for r in csv.DictReader(open(ROOT / "em" / "persona_space" / "role_valence.csv"))}
    seen, out = set(s1), []
    for cat, items in zip(CATEGORIES, lists):
        k = 0
        for x in items:
            n = norm(x["name"])
            if n and n not in seen:
                seen.add(n)
                out.append(x)
                k += 1
        print(f"{cat}: {len(items)} generated, {k} kept", flush=True)
    with open(OUT, "w") as f:
        for i, x in enumerate(out):
            f.write(json.dumps(dict(id=f"s3_{i:04d}", **x)) + "\n")
    print(f"wrote {len(out)} personas to {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    asyncio.run(main())
